class Solution {
    public long countGoodIntegers(int n, int k) {
        int half = (n + 1) / 2;
        int start = 1;
        for (int i = 0; i < half - 1; ++i) start *= 10;
        int end = start * 10;

        Set<String> validMultisets = new HashSet<>();
        for (int num = start; num < end; ++num) {
            String s = Integer.toString(num);
            StringBuilder pal = new StringBuilder(s);
            if (n % 2 == 1) {
                for (int i = s.length() - 2; i >= 0; --i) pal.append(s.charAt(i));
            } else {
                for (int i = s.length() - 1; i >= 0; --i) pal.append(s.charAt(i));
            }
            if (Long.parseLong(pal.toString()) % k == 0) {
                int[] counts = new int[10];
                for (int i = 0; i < pal.length(); ++i) counts[pal.charAt(i) - '0']++;
                validMultisets.add(Arrays.toString(counts));
            }
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i;

        long ans = 0;
        for (String m : validMultisets) {
            String[] parts = m.substring(1, m.length() - 1).split(", ");
            int[] counts = new int[10];
            for (int i = 0; i < 10; ++i) counts[i] = Integer.parseInt(parts[i]);
            long total = fact[n];
            for (int d = 0; d < 10; ++d) total /= fact[counts[d]];
            if (counts[0] > 0) {
                long withZero = fact[n - 1];
                withZero /= fact[counts[0] - 1];
                for (int d = 1; d < 10; ++d) withZero /= fact[counts[d]];
                total -= withZero;
            }
            ans += total;
        }
        return ans;
    }
}

var countGoodIntegers = function(n, k) {
    const half = Math.floor((n + 1) / 2);
    const start = Math.pow(10, half - 1);
    const end = Math.pow(10, half);

    const validMultisets = new Set();
    for (let num = start; num < end; num++) {
        const s = String(num);
        let pal = s;
        if (n % 2 === 1) {
            for (let i = s.length - 2; i >= 0; i--) pal += s[i];
        } else {
            for (let i = s.length - 1; i >= 0; i--) pal += s[i];
        }
        if (BigInt(pal) % BigInt(k) === 0n) {
            const counts = new Array(10).fill(0);
            for (let i = 0; i < pal.length; i++) counts[Number(pal[i])]++;
            validMultisets.add(counts.join(','));
        }
    }

    const fact = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * BigInt(i);

    let ans = 0n;
    for (const m of validMultisets) {
        const counts = m.split(',').map(Number);
        let total = fact[n];
        for (let d = 0; d < 10; d++) total /= fact[counts[d]];
        if (counts[0] > 0) {
            let withZero = fact[n - 1];
            withZero /= fact[counts[0] - 1];
            for (let d = 1; d < 10; d++) withZero /= fact[counts[d]];
            total -= withZero;
        }
        ans += total;
    }
    return Number(ans);
};
